{ "World", "Goodbye" }
);", "[] 
{ "Hello", "World", "Goodbye" }
);
		assertEquals(expectedSubList, subList);
		assertEquals(expectedParentList, uniqueList);
		assertTrue(uniqueList.contains("Goodbye")); // fails
	}
