import java.nio.charset.", "Charset;

import org.jsoup.", "Test;

public class ShiftJisTest {

    @Test
    public void testShiftJisRoundtrip() throws Exception {
        String input = 
            "<html>"
          +   "<head>"
          +     "<meta http-equiv=\"content-type\" content=\"text/html; charset=Shift_JIS\" />"
          +   "</head>"
          +   "<body>"
          +     "before&nbsp;after"
          +   "</body>"
          + "</html>";
        InputStream is = new ByteArrayInputStream(input.getBytes(Charset.forName("ASCII")));

        Document doc = Jsoup.parse(is, null, "http://example.com");
        doc.outputSettings().escapeMode(EscapeMode.xhtml);

        String output = new String(doc.html().getBytes(doc.outputSettings().charset()), doc.outputSettings().charset());

        System.out.println(output);

        Assert.assertFalse("Should not have contained a '?'.", "I assume the issue here is that I've asked JSoup to escape only XHTML characters (i.e. not nbsp), and it's producing a charset where (I assume) there's no character to represent 'non-breaking space'."]

