["AUTO_DETECT_GETTERS/SETTERS #1223New issueCopy linkNew issueCopy linkClosedClosedBasicClassIntrospector.forSerialization(...).findProperties should respect MapperFeature.", "AUTO_DETECT_GETTERS/SETTERS#1223Copy linkMilestone2.7.5Descriptionheadw01opened on May 6, 2016Issue body actionsWhen I set the ObjectMapper MapperConfig to not AutoDetect and use the BasicClassIntrospector to get the properties, I seem to still be getting the Methods.", "Found property: name=groupname, internalName=groupname
public static void main(String [] args) {
    class TCls {
        @JsonProperty("groupname")
        private String groupname;

        public void setName(String str) {
            this.groupname = str;
        }
        public String getName() {
            return groupname;
        }
    }

    ObjectMapper om = new ObjectMapper();
    // Only use explicitly specified values to be serialized/deserialized (i.e., JSONProperty).
    om.configure(com.fasterxml.jackson.databind.", "AUTO_DETECT_SETTERS, false);
    om.configure(com.fasterxml.jackson.databind.", "USE_GETTERS_AS_SETTERS, false);
    om.configure(com.fasterxml.jackson.databind.", "USE_ANNOTATIONS, true);

    JavaType javaType = om.getTypeFactory().constructType(TCls.class);

    BasicClassIntrospector introspector = new BasicClassIntrospector();
    BasicBeanDescription bdesc = introspector.forSerialization(om.getSerializationConfig(), javaType, null);
    List<BeanPropertyDefinition> bprops = bdesc.findProperties();

    if (1 != bprops.size()) {
        System.out.println("Found property count " + bprops.size() + ", there should only be one??");
    }
    bprops.forEach(prop -> {
        System.out.println("Found property: name=" + prop.getName() + ", internalName=" + prop.getInternalName());
    });
}
